INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '剩余求总量', 'kp-eng-d-remain-to-total', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "剩余求总量"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知干了几天后，还剩下【具体的绝对数量】没干完，反推总工程量。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典句式：“甲乙合作 5 天后，还剩下 1000 米路没有修。已知甲单独修要……”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心逻辑"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "与“已完求总量”一模一样，只不过桥梁变成了【剩余的虚拟份数】。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[先完全不管那个绝对数量(1000米)] --> B[走标准流程: 赋W份数, 出P份数]\nB --> C[模拟前5天, 算出消耗掉的虚拟份数]\nC --> D[用总W份数 - 消耗份数 = 剩余虚拟份数]\nD --> E[真实剩余量(1000) ÷ 剩余虚拟份数 = 换算系数 k]\nE --> F[总工作量 = W份数 × k]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲需 20 天，乙需 30 天。两人合作 8 天后，还剩 600 个零件没加工。求总零件数？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "虚拟推演：20和30公倍数 60。W=60份。P甲=3，P乙=2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算消耗：两人合作 8 天，消耗了 (3+2) × 8 = 40 份。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算剩余份数：剩下 60 - 40 = 20 份。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "建立桥梁：这 20 份对应真实的 600 个零件。换算系数 k = 600 ÷ 20 = 30（即1份是30个）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求真实总量：总共 60 份。真实总量 = 60 × 30 = 1800 个。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记乘以总份数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "算出 1份 = 30 之后，很多同学兴奋过头，选项里正好有个 30，直接选了。拜托！人家问的是总零件数，一定要拿着这个 30 去乘以最初你赋予的 W(60)！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在草稿纸上，虚拟量用圆圈圈起来（如 ⑥⓪），真实量直接写。时刻保持清醒，圈里的数不能和外面的数直接加减。"}]}]}$$ AS jsonb), NULL, '剩余求总量的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "剩余求总量"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_d_remain_to_total", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
